import os, re, collections
root_dir='AlgebraicJacobian'
mods={}
for dp,_,fns in os.walk(root_dir):
    for fn in fns:
        if fn.endswith('.lean'):
            p=os.path.join(dp,fn)
            mod=p[:-5].replace('/','.')
            mods[mod]=p
mods['AlgebraicJacobian']='AlgebraicJacobian.lean'
imp=collections.defaultdict(set)
for m,p in mods.items():
    try:
        for line in open(p,encoding='utf-8',errors='replace'):
            mm=re.match(r'^import\s+(AlgebraicJacobian[\w.]*)',line)
            if mm: imp[m].add(mm.group(1))
    except Exception as e: pass
seen=set(); stack=['AlgebraicJacobian']
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    for d in imp[m]:
        if d not in seen: stack.append(d)
allm=set(mods)
unrooted=sorted(allm-seen)
print("total modules (incl root):",len(allm))
print("rooted (transitive closure):",len(seen&allm))
print("UNROOTED:",len(unrooted))
for u in unrooted[:130]: print("  ",u)
